# Seed tool: multi-engine web search (all / baidu / sogou / ddg).
# ponytail: baidu/sogou 返回跳转链接不展开；解析选择器随站点改版会失效，Agent 可自更新本脚本。
import json
import urllib.parse
from concurrent.futures import ThreadPoolExecutor

import requests
from bs4 import BeautifulSoup

_UA_ANDROID = "Mozilla/5.0 (Linux; Android 14) AppleWebKit/537.36"
_UA_DESKTOP = "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36"


def main(query: str, engine: str = "all", max_results: int = 8):
    '''Search the web. engine: "all" (default, merges Baidu + Sogou + DuckDuckGo), "baidu", "sogou" or "ddg". Returns a list of {title, url, snippet}.'''
    engines = ("baidu", "sogou", "ddg") if engine == "all" else (engine,)
    with ThreadPoolExecutor(max_workers=len(engines)) as pool:
        futures = [pool.submit(_search, e, query, max_results) for e in engines]
        # ddg 在无代理网络会超时，给短 timeout 快速失败，不拖慢整体
        fetched = []
        for e, fut in zip(engines, futures):
            try:
                fetched.append(fut.result(timeout=20))
            except Exception:
                fetched.append([])
    print(json.dumps(_merge(fetched, max_results), ensure_ascii=False))


def _search(engine: str, query: str, max_results: int):
    if engine == "baidu":
        # baidu 桌面 UA 会触发验证码，必须移动 UA
        resp = requests.get(
            "https://www.baidu.com/s",
            params={"wd": query},
            headers={"User-Agent": _UA_ANDROID},
            timeout=15,
        )
        parser = _parse_baidu
    elif engine == "sogou":
        resp = requests.get(
            "https://www.sogou.com/web",
            params={"query": query},
            headers={"User-Agent": _UA_DESKTOP},
            timeout=15,
        )
        parser = _parse_sogou
    else:
        resp = requests.post(
            "https://html.duckduckgo.com/html/",
            data={"q": query},
            headers={"User-Agent": _UA_ANDROID},
            timeout=8,
        )
        parser = _parse_ddg
    resp.raise_for_status()
    soup = BeautifulSoup(resp.text, "html.parser")
    return parser(soup, max_results)


def _merge(lists, max_results):
    seen = set()
    merged = []
    for group in lists:
        for item in group:
            url = item.get("url", "")
            if url in seen:
                continue
            seen.add(url)
            merged.append(item)
            if len(merged) >= max_results:
                return merged
    return merged


def _parse_ddg(soup, max_results):
    results = []
    for item in soup.select("div.result.results_links")[: max_results]:
        link = item.select_one("a.result__a")
        if link is None:
            continue
        snippet_el = item.select_one("td.result__snippet") or item.select_one(".result__snippet")
        _append(results, link.get_text(strip=True), _clean_ddg_url(link.get("href", "")), snippet_el)
        if len(results) >= max_results:
            break
    return results


def _parse_baidu(soup, max_results):
    results = []
    for item in soup.select("div.c-result"):
        if len(results) >= max_results:
            break
        title_el = item.select_one("h3")
        if title_el is None:
            continue
        try:
            url = json.loads(item.get("data-log", "{}")).get("mu", "")
        except ValueError:
            url = ""
        snippet_el = None
        for sel in ("[class*=content-right]", "[class*=abstract]", "[class*=clamp]", "[class*=desc]"):
            candidate = item.select_one(sel)
            if candidate is not None:
                snippet_el = candidate
                break
        _append(results, title_el.get_text(strip=True), url, snippet_el)
    return results


def _parse_sogou(soup, max_results):
    results = []
    for item in soup.select("div.vrwrap, div.rb"):
        if len(results) >= max_results:
            break
        link = item.select_one("h3 a")
        if link is None:
            continue
        snippet_el = item.select_one(".str-text-info") or item.select_one(".str_info") or item.select_one(".space-txt")
        _append(results, link.get_text(strip=True), _clean_sogou_url(link.get("href", "")), snippet_el)
    return results


def _append(results, title, url, snippet_el):
    snippet = snippet_el.get_text(strip=True) if snippet_el else ""
    if title and url:
        results.append({"title": title, "url": url, "snippet": snippet})


def _clean_ddg_url(href: str) -> str:
    if href.startswith("//duckduckgo.com/l/") or href.startswith("https://duckduckgo.com/l/"):
        parsed = urllib.parse.urlparse(href if href.startswith("http") else "https:" + href)
        target = urllib.parse.parse_qs(parsed.query).get("uddg", [""])[0]
        return urllib.parse.unquote(target)
    return href


def _clean_sogou_url(href: str) -> str:
    if href.startswith("/link"):
        return "https://www.sogou.com" + href
    return href

# Seed tool: fetch a URL and extract readable article text (companion to py_web_search,
# use when search only gives snippets and the full page is needed).
# ponytail: article-container selectors break on site redesigns; Agent can self-update this script.
import re
import html
import requests


def _clean(s: str) -> str:
    s = re.sub(r'[ \t\u00a0\u3000]+', ' ', s)
    s = re.sub(r'\n\s*\n+', '\n', s)
    return '\n'.join(line.strip() for line in s.split('\n') if line.strip())


def _extract_article(raw: str) -> str:
    # 1) <article> block
    m = re.search(r'<article\b[\s\S]*?</article>', raw, re.I)
    if m:
        return m.group(0)

    # 2) common article container div, depth-aware closing match
    m = re.search(
        r'<div\b[^>]*(?:art_content|artibody|article-content|article_content|article|content)[^>]*>',
        raw, re.I,
    )
    if m:
        start = m.start()
        depth = 0
        i = start
        while i < len(raw):
            op = re.match(r'<div\b[^>]*>', raw[i:], re.I)
            cl = re.match(r'</div\s*>', raw[i:], re.I)
            if cl:
                depth -= 1
                if depth <= 0:
                    return raw[start:i + cl.end()]
                i += cl.end()
                continue
            if op:
                tag = op.group(0)
                if not tag.rstrip().endswith('/>'):
                    depth += 1
                i += op.end()
                continue
            i += 1
        return raw[start:]

    # 3) <body> fallback
    m = re.search(r'<body\b[\s\S]*?</body>', raw, re.I)
    if m:
        return m.group(0)

    return raw


def _decoded_text(r) -> str:
    enc = None
    m = re.search(r'charset=["\']?([\w-]+)', r.headers.get('Content-Type', ''), re.I)
    if m:
        enc = m.group(1)
    if not enc:
        m = re.search(r'<meta[^>]+charset=["\']?([\w-]+)', r.text[:2000], re.I)
        if m:
            enc = m.group(1)
    candidates = [enc, 'utf-8', 'gb18030']
    for c in candidates:
        if not c:
            continue
        try:
            r.encoding = c
            return r.text
        except Exception:
            continue
    return r.text


def main(url: str, keyword: str = "", max_chars: int = 6000, timeout: int = 25):
    """抓取网页并提取可读正文。可选 keyword：只返回关键词附近的一整段文本（定位到后前后各取一半 max_chars）。
    当 py_web_search 只给摘要、需要读全文时使用。"""
    headers = {
        'User-Agent': 'Mozilla/5.0 (Linux; Android 12; Pixel 6) AppleWebKit/537.36 '
                      '(KHTML, like Gecko) Chrome/120.0 Mobile Safari/537.36',
        'Accept-Language': 'zh-CN,zh;q=0.9,en;q=0.8',
    }
    r = requests.get(url, headers=headers, timeout=timeout)
    r.raise_for_status()
    raw = _decoded_text(r)

    # strip noisy blocks
    raw = re.sub(r'<(script|style|noscript|iframe|svg)[\s\S]*?</\1>', ' ', raw, flags=re.I)
    raw = re.sub(r'<head[\s\S]*?</head>', ' ', raw, flags=re.I)

    body = _extract_article(raw)
    body = re.sub(r'<(script|style|noscript)[\s\S]*?</\1>', ' ', body, flags=re.I)

    text = re.sub(r'<[^>]+>', '\n', body)
    text = html.unescape(text)
    text = _clean(text)

    if keyword:
        idx = text.lower().find(keyword.lower())
        if idx >= 0:
            start = max(0, idx - max_chars // 2)
            text = text[start:start + max_chars]
        else:
            text = text[:max_chars]
    else:
        text = text[:max_chars]

    print(text)

import shlex
import subprocess
import sys


def su_run(args, timeout=15):
    """在 root 下执行命令；找不到 su 时抛 FileNotFoundError。"""
    cmd = ["su", "-c", " ".join(shlex.quote(a) for a in args)]
    return subprocess.run(cmd, capture_output=True, text=True, timeout=timeout)


def main():
    '''启动微信 (Launch WeChat).'''
    # 非 root 直接 am start 会 SecurityException: Permission Denied；经 su 执行，
    # 首次调用会弹出 su 授权对话框，同意后启动。
    try:
        result = su_run(["am", "start", "-n", "com.tencent.mm/com.tencent.mm.ui.LauncherUI"])
    except FileNotFoundError:
        print("未找到 su：需要 root（Magisk / KernelSU 授权后重试）", file=sys.stderr)
        raise SystemExit(2)
    if result.returncode != 0:
        print((result.stderr or result.stdout).strip())
        raise SystemExit(1)
    print("WeChat launched.")

"""Raw location access for the agent (backed by Android LocationManager)."""
import json
import time


def _to_list(java_list):
    if java_list is None:
        return []
    out = []
    for i in range(java_list.size()):
        out.append(str(java_list.get(i)))
    return out


def _describe(loc):
    now_ms = int(time.time() * 1000)
    d = {
        "provider": str(loc.getProvider()),
        "lat": round(loc.getLatitude(), 7),
        "lon": round(loc.getLongitude(), 7),
        "time_iso": time.strftime("%Y-%m-%dT%H:%M:%S", time.localtime(loc.getTime() / 1000.0)),
        "age_s": round((now_ms - loc.getTime()) / 1000.0, 1),
    }
    if loc.hasAccuracy():
        d["accuracy_m"] = round(loc.getAccuracy(), 1)
    if loc.hasAltitude():
        d["altitude_m"] = round(loc.getAltitude(), 1)
    if loc.hasSpeed():
        d["speed_mps"] = round(loc.getSpeed(), 2)
    if loc.hasBearing():
        d["bearing_deg"] = round(loc.getBearing(), 1)
    try:
        extras = loc.getExtras()
        if extras is not None:
            for key in ("satellites", "maxCn0", "meanCn0"):
                if extras.containsKey(key):
                    d[key] = extras.getInt(key)
    except Exception:
        pass
    return d


def main(fresh: bool = True, timeout_s: int = 12) -> str:
    """Read raw GPS data from this phone: latitude, longitude, accuracy, altitude, speed,
    bearing and satellite count. Returns the last-known fix for every provider plus, when
    fresh is true, a new fix from gps/network/fused."""
    result = _run(fresh, timeout_s)
    print(result)
    return result


def _run(fresh: bool = True, timeout_s: int = 12) -> str:
    from com.chaquo.python import Python as CQ

    ctx = CQ.getPlatform().getApplication()
    pm = ctx.getPackageManager()
    pkg = ctx.getPackageName()
    fine = pm.checkPermission("android.permission.ACCESS_FINE_LOCATION", pkg) == 0
    coarse = pm.checkPermission("android.permission.ACCESS_COARSE_LOCATION", pkg) == 0

    if not (fine or coarse):
        return json.dumps({
            "error": "No location permission granted to the app.",
            "fine": fine,
            "coarse": coarse,
            "how_to_fix": "Grant it in Settings > Apps > Evergrow > Permissions > Location. "
                          "If Location is not listed there, the installed APK predates the "
                          "manifest change and needs the newer build.",
        }, indent=1)

    lm = ctx.getSystemService("location")
    if lm is None:
        return json.dumps({"error": "LocationManager unavailable"})

    result = {
        "permission": {"fine": fine, "coarse": coarse},
        "providers_available": _to_list(lm.getAllProviders()),
        "providers_enabled": _to_list(lm.getProviders(True)),
        "last_known": {},
    }
    for provider in result["providers_available"]:
        try:
            loc = lm.getLastKnownLocation(provider)
        except Exception as exc:
            result.setdefault("last_known_errors", {})[provider] = str(exc)
            continue
        if loc is not None:
            result["last_known"][provider] = _describe(loc)

    if not fresh:
        return json.dumps(result, indent=1)

    from java import dynamic_proxy
    from android.location import LocationListener
    from android.os import Looper

    best = {"loc": None}

    class OneShot(dynamic_proxy(LocationListener)):
        def onLocationChanged(self, location):
            # 回调里抛异常会一路冒到 Java 主线程，把整个应用带崩（21:47 那次崩溃就是这样）。
            # 所以这里整体包一层：定位数据再怎么离谱也不许打断进程。
            try:
                # API 31+ 还有一个 onLocationChanged(List<Location>) 重载，
                # 动态代理会把它也派发到这里，所以先判断拿到的是不是单点。
                if hasattr(location, "getProvider"):
                    candidates = [location]
                else:
                    candidates = [location.get(i) for i in range(location.size())]
                for loc in candidates:
                    if loc is None or not hasattr(loc, "getAccuracy"):
                        continue
                    cur = best["loc"]
                    if cur is None or loc.getAccuracy() < cur.getAccuracy():
                        best["loc"] = loc
            except Exception:
                pass

        def onProviderEnabled(self, provider):
            pass

        def onProviderDisabled(self, provider):
            pass

        def onStatusChanged(self, provider, status, extras):
            pass

    listener = OneShot()
    looper = Looper.getMainLooper()
    requested = []
    for provider in ("gps", "network", "fused"):
        try:
            lm.requestLocationUpdates(provider, 0, 0, listener, looper)
            requested.append(provider)
        except Exception as exc:
            result.setdefault("request_errors", {})[provider] = str(exc)
    result["requested"] = requested

    limit = time.time() + max(1, min(int(timeout_s), 30))
    try:
        while time.time() < limit and best["loc"] is None:
            time.sleep(0.25)
    finally:
        try:
            lm.removeUpdates(listener)
        except Exception:
            pass

    result["fix"] = _describe(best["loc"]) if best["loc"] is not None else None
    if best["loc"] is None:
        result["note"] = ("No fresh fix within %ss. Location services may be off, or there is no "
                          "sky view / network. last_known values above are still usable." % timeout_s)
    return json.dumps(result, indent=1)

"""Run tracking for the agent: start a GPS session, then report distance, time and pace."""
import json
import math
import os
import time

SERVICE_CLASS = "com.niki914.zafiro.app.location.RunTrackingService"
ACTION_START = "com.niki914.zafiro.action.RUN_START"

# 精度差于这个值的点直接丢掉：网络定位动辄 ±100m，留着会把距离吹上天
MAX_ACCURACY_M = 60.0
# 两个点之间隔这么久，说明中途停过（或应用被杀），不计入平均配速
PAUSE_GAP_S = 45.0


def _app():
    from com.chaquo.python import Python as CQ
    return CQ.getPlatform().getApplication()


def _files(ctx):
    return str(ctx.getFilesDir())


def _points_path(ctx):
    return os.path.join(_files(ctx), "run_points.jsonl")


def _marker_path(ctx):
    return os.path.join(_files(ctx), "run_active")


def _running(ctx):
    return os.path.exists(_marker_path(ctx))


def _intent(ctx, action):
    from android.content import Intent
    it = Intent()
    it.setClassName(ctx.getPackageName(), SERVICE_CLASS)
    it.setAction(action)
    return it


def _start(ctx):
    # 只有启动才用 startForegroundService（并立刻在前台服务里 startForeground）
    ctx.startForegroundService(_intent(ctx, ACTION_START))


def _stop(ctx):
    """停止用 stopService，不要用 startForegroundService 发命令。

    之前就是这么写的：用 startForegroundService() 送一个 STOP action 进去，而服务在
    STOP 分支里直接 stopSelf()，于是不满足「5 秒内必须 startForeground」的契约，
    系统抛 ForegroundServiceDidNotStartInTimeException 把整个应用杀掉。
    stopService 直接销毁服务，onDestroy 会注销定位回调，没有这个坑。
    """
    return bool(ctx.stopService(_intent(ctx, ACTION_START)))


def _load(path):
    """读点，但只保留最后一条 start 标记之后的部分。

    服务改成追加写入（不再清空文件），所以同一个文件里会有多次会话；
    start 标记负责切分，历史轨迹因此不会丢。
    """
    rows = []
    if not os.path.exists(path):
        return []
    with open(path) as fh:
        for line in fh:
            line = line.strip()
            if not line:
                continue
            try:
                rows.append(json.loads(line))
            except ValueError:
                continue
    cut = 0
    for i, r in enumerate(rows):
        if r.get("event") == "start":
            cut = i + 1
    return [r for r in rows[cut:] if "lat" in r]


def _haversine(a, b):
    r = 6371000.0
    p1, p2 = math.radians(a["lat"]), math.radians(b["lat"])
    dp = p2 - p1
    dl = math.radians(b["lon"] - a["lon"])
    h = math.sin(dp / 2) ** 2 + math.cos(p1) * math.cos(p2) * math.sin(dl / 2) ** 2
    return 2 * r * math.asin(min(1.0, math.sqrt(h)))


def _summarise(pts, running):
    good = [p for p in pts if (p.get("acc") or -1) >= 0 and p["acc"] <= MAX_ACCURACY_M]
    if len(good) < 2:
        return {
            "points": len(pts),
            "usable_points": len(good),
            "distance_m": 0.0,
            "running": running,
            "note": "Not enough accurate GPS points yet.",
        }

    distance = 0.0
    moving_s = 0.0
    splits = []
    km_mark = 1000.0
    since_mark = 0.0
    prev = good[0]
    max_speed = 0.0
    for cur in good[1:]:
        dt = (cur["t"] - prev["t"]) / 1000.0
        if dt <= 0:
            continue
        step = _haversine(prev, cur)
        # 一秒内跑出 15m（54km/h）只能是 GPS 漂移
        if step / dt > 15.0:
            prev = cur
            continue
        distance += step
        since_mark += step
        if dt <= PAUSE_GAP_S:
            moving_s += dt
        max_speed = max(max_speed, step / dt)
        if since_mark >= km_mark:
            splits.append({"km": len(splits) + 1, "seconds": round(moving_s, 1)})
            km_mark += 1000.0
        prev = cur

    elapsed = (good[-1]["t"] - good[0]["t"]) / 1000.0
    pace = round((moving_s / 60.0) / (distance / 1000.0), 2) if distance > 50 and moving_s > 0 else None
    return {
        "points": len(pts),
        "usable_points": len(good),
        "distance_m": round(distance, 1),
        "distance_km": round(distance / 1000.0, 2),
        "elapsed_s": round(elapsed, 1),
        "elapsed": time.strftime("%H:%M:%S", time.gmtime(elapsed)),
        "moving_s": round(moving_s, 1),
        "avg_pace_min_per_km": pace,
        "avg_speed_kmh": round((distance / moving_s) * 3.6, 2) if moving_s > 0 else None,
        "max_speed_kmh": round(max_speed * 3.6, 2) if max_speed else None,
        "splits": splits,
        "started_at": time.strftime("%Y-%m-%dT%H:%M:%S", time.localtime(good[0]["t"] / 1000.0)),
        "last_point_age_s": round(time.time() - good[-1]["t"] / 1000.0, 1),
        "running": running,
    }


def main(action: str = "status") -> str:
    """Track a run: action=start begins a GPS session in a foreground service,
    action=stop ends it, action=status or stop returns distance, elapsed time and pace."""
    result = _run(action)
    print(result)
    return result


def _run(action: str = "status") -> str:
    ctx = _app()
    path = _points_path(ctx)
    act = (action or "status").strip().lower()

    if act == "start":
        try:
            _start(ctx)
        except Exception as exc:
            return json.dumps({
                "error": "Could not start the tracking service: " + str(exc),
                "hint": "Android only allows starting a foreground service while the app is "
                        "in the foreground.",
            }, indent=1)
        time.sleep(1.5)
        return json.dumps({
            "started": True,
            "service": SERVICE_CLASS,
            "running": _running(ctx),
            "points_so_far": len(_load(path)),
            "note": "Session file reset. First GPS point usually lands within a few seconds.",
        }, indent=1)

    if act in ("stop", "end"):
        try:
            _stop(ctx)
        except Exception as exc:
            summary = _summarise(_load(path), running=False)
            summary["stop_warning"] = str(exc)
            return json.dumps(summary, indent=1)
        time.sleep(0.8)
        summary = _summarise(_load(path), running=False)
        summary["stopped"] = True
        return json.dumps(summary, indent=1)

    return json.dumps(_summarise(_load(path), running=_running(ctx)), indent=1)

"""News in two tiers: a sub-second fast batch, plus a Google News deep batch fetched in the
background so it is already cached by the time the first batch has been read aloud."""
import json
import os
import threading
import time
import xml.etree.ElementTree as ET

import requests

CACHE_TTL_S = 900
DEEP_TIMEOUT_S = 70
BASE = "/data/user/0/com.niki914.zafiro.evergrow.debug/files/"

GN = "https://news.google.com/rss/search?q=%s&hl=en-US&gl=US&ceid=US:en"
SCMP = "https://www.scmp.com/rss/91/feed"
DEEPSEEK = "https://api.deepseek.com/v1/tools/search"
OPENROUTER = "https://openrouter.ai/api/v1/chat/completions"

SERPAPI = "https://serpapi.com/search.json"
SERPAPI_KEY = BASE + "tool_output/serpapi/.token"

# 每个板块一条 Google News 查询。用 tbm=nws 拿带日期的新闻，
# 比 Exa 的 13-25 秒快一个数量级，而且来源是 Google 的排序本身。
DEEP_QUERY = {
    "world": "world news today",
    "tech": "technology AI news today",
    "football": "Premier League results today",
    "hk": "Hong Kong news today",
}

_state = {"thread": None}
_lock = threading.Lock()


def _cache_path():
    return os.path.join(BASE, "news_deep_cache.json")


def _secret(rel):
    with open(BASE + rel) as fh:
        return fh.read().strip()


def _deepseek_key():
    cfg = json.load(open(BASE + "settings/llm/saved_configs.json"))

    def walk(o):
        if isinstance(o, dict):
            for k, v in o.items():
                if k in ("api_key", "apiKey") and isinstance(v, str) and v.startswith("sk-"):
                    return v
                r = walk(v)
                if r:
                    return r
        if isinstance(o, list):
            for it in o:
                r = walk(it)
                if r:
                    return r
        return None

    return walk(cfg)


def _rss(url, limit=6):
    last, root = None, None
    for attempt in range(2):
        try:
            r = requests.get(url, timeout=10, headers={"User-Agent": "Mozilla/5.0 (EverGrow)"})
            if r.status_code != 200:
                raise RuntimeError("HTTP %s" % r.status_code)
            root = ET.fromstring(r.content)
            break
        except Exception as exc:
            last = exc
            time.sleep(0.4 * (attempt + 1))
    if root is None:
        raise last
    out = []
    for item in root.iter("item"):
        out.append({
            "title": (item.findtext("title") or "").strip(),
            "date": (item.findtext("pubDate") or "").strip(),
            "url": (item.findtext("link") or "").strip(),
        })
        if len(out) >= limit:
            break
    return out


def _deepseek_hk(limit=6):
    try:
        r = requests.post(
            DEEPSEEK,
            headers={"Authorization": "Bearer " + (_deepseek_key() or "")},
            json={"query": "香港 新聞 今日 頭條", "count": limit, "need_content": False},
            timeout=12,
        )
        items = (r.json() or {}).get("results") or []
        return [{
            "title": (it.get("title") or "").strip(),
            "date": (it.get("date") or "").strip(),
            "url": (it.get("url") or "").strip(),
        } for it in items if it.get("date")]
    except Exception:
        return []


def _tier0(section):
    if section == "hk":
        items = _rss(GN % "Hong%20Kong")
        try:
            items += [i for i in _rss(SCMP) if i["date"]]
        except Exception:
            pass
        items += _deepseek_hk()
    elif section == "football":
        items = _rss(GN % "Premier%20League")
    elif section == "tech":
        items = _rss(GN % "technology%20AI")
    else:
        items = _rss(GN % "world%20news")
    seen, out = set(), []
    for it in items:
        key = it["title"][:60].lower()
        if not it["title"] or not it["date"] or key in seen:
            continue
        seen.add(key)
        out.append(it)
    return out[:5]


def _deep(section):
    """Google News 深度批：SerpApi 的 tbm=nws，返回带日期和来源的条目。"""
    with open(SERPAPI_KEY) as fh:
        key = fh.read().strip()
    params = {"q": DEEP_QUERY[section], "api_key": key, "num": 6,
              "hl": "en", "gl": "hk", "tbm": "nws"}
    r = requests.get(SERPAPI, params=params, timeout=25)
    if r.status_code != 200:
        raise RuntimeError("HTTP %s" % r.status_code)
    j = r.json()
    items = j.get("news_results") or j.get("organic_results") or []
    lines, urls = [], []
    for it in items[:6]:
        title = (it.get("title") or "").strip()
        if not title:
            continue
        date = (it.get("date") or "").strip()
        src_name = it.get("source")
        if isinstance(src_name, dict):
            src_name = src_name.get("name")
        snippet = (it.get("snippet") or "").strip()
        lines.append("- [%s] %s%s%s" % (date, title,
                                        (" (" + str(src_name) + ")") if src_name else "",
                                        (": " + snippet) if snippet else ""))
        if it.get("link"):
            urls.append(it["link"])
    return {"text": "\n".join(lines)[:2200], "urls": urls[:6]}


def _deep_worker(sections):
    import concurrent.futures as cf

    state = {"started": time.time(), "status": "running", "sections": {}}
    json.dump(state, open(_cache_path(), "w"))

    def dump():
        with _lock:
            json.dump(state, open(_cache_path(), "w"))

    with cf.ThreadPoolExecutor(max_workers=max(1, len(sections))) as ex:
        futures = {ex.submit(_deep, sec): sec for sec in sections}
        for fut in cf.as_completed(futures):
            sec = futures[fut]
            try:
                state["sections"][sec] = fut.result()
            except Exception as exc:
                state["sections"][sec] = {"error": str(exc)}
            dump()

    state["status"] = "done"
    state["finished"] = time.time()
    dump()


def _start_deep(sections):
    existing = _read_cache()
    if existing and (time.time() - existing.get("started", 0)) < CACHE_TTL_S:
        return "already cached" if existing.get("status") == "done" else "already running"
    with _lock:
        th = _state.get("thread")
        if th is not None and th.is_alive():
            return "already running"
        json.dump({"started": time.time(), "status": "running", "sections": {}},
                  open(_cache_path(), "w"))
        th = threading.Thread(target=_deep_worker, args=(sections,), daemon=True)
        _state["thread"] = th
        th.start()
    return "started"


def _read_cache():
    try:
        return json.load(open(_cache_path()))
    except Exception:
        return None


def _run(mode, sections):
    want = [s.strip().lower() for s in (sections or "").split(",") if s.strip()]
    want = [s for s in want if s in ("world", "tech", "football", "hk")] or ["world", "tech"]

    if mode == "status":
        cache = _read_cache() or {}
        return json.dumps({
            "status": cache.get("status", "none"),
            "age_s": round(time.time() - cache["started"], 1) if cache.get("started") else None,
            "sections_ready": sorted((cache.get("sections") or {}).keys()),
        }, indent=1)

    if mode in ("deep", "deepen"):
        cache = _read_cache() or {}
        deadline = time.time() + 20
        while cache.get("status") == "running" and time.time() < deadline:
            time.sleep(1.0)
            cache = _read_cache() or {}
        return json.dumps({
            "status": cache.get("status", "none"),
            "age_s": round(time.time() - cache["started"], 1) if cache.get("started") else None,
            "sections": cache.get("sections", {}),
        }, indent=1)

    t0 = time.time()
    fast, errors = {}, {}
    threads = {}

    for section in want:
        def job(sec=section):
            try:
                fast[sec] = _tier0(sec)
            except Exception as exc:
                fast[sec] = []
                errors[sec] = type(exc).__name__ + ": " + str(exc)[:120]

        th = threading.Thread(target=job, daemon=True)
        threads[section] = th
        th.start()
    for th in threads.values():
        th.join(timeout=12)

    kickoff = _start_deep(want)
    return json.dumps({
        "tier": "fast",
        "elapsed_s": round(time.time() - t0, 2),
        "sections": {k: fast.get(k, []) for k in want},
        "errors": errors,
        "deep_fetch": kickoff,
        "note": "Google News deep fetch runs in the background; call mode=deep once the first "
                "batch has been spoken, or mode=status to check.",
    }, indent=1)


def main(mode: str = "fast", sections: str = "world,tech") -> str:
    """News in two tiers. mode=fast returns dated headlines in about a second and kicks off the
    Google News deep fetch in the background; mode=deep returns those write-ups (already cached if
    the fast call has had time to run); mode=status reports the background fetch."""
    out = _run(mode, sections)
    print(out)
    return out

"""Re-transcribe a stored listen-mode utterance with Qwen ASR, to check whether the phone's
recogniser misheard. Clips are kept by the app in files/utt/ with the original transcript."""
import base64
import glob
import json
import os
import time

import requests

BASE = "/data/user/0/com.niki914.zafiro.evergrow.debug/files/"
ENDPOINT = "https://maas.qwencloudapi.com/compatible-mode/v1/chat/completions"
MODEL = "qwen3-asr-flash"


def _key():
    with open(BASE + "qwen_asr_key.txt") as fh:
        return fh.read().strip()


def _clips():
    files = glob.glob(BASE + "utt/utt_*.wav")
    return sorted(files, key=lambda p: os.path.getmtime(p), reverse=True)


def _transcribe(path):
    with open(path, "rb") as fh:
        encoded = base64.b64encode(fh.read()).decode()
    body = {
        "model": MODEL,
        "messages": [{
            "role": "user",
            "content": [{
                "type": "input_audio",
                "input_audio": {"data": "data:audio/wav;base64," + encoded},
            }],
        }],
    }
    r = requests.post(ENDPOINT, headers={"Authorization": "Bearer " + _key()},
                      json=body, timeout=60)
    if r.status_code != 200:
        return {"error": "HTTP %s" % r.status_code, "body": r.text[:200]}
    j = r.json()
    try:
        return {"text": j["choices"][0]["message"]["content"]}
    except Exception:
        return {"error": "unexpected response", "body": json.dumps(j)[:200]}


def _run(index, list_only):
    clips = _clips()
    if not clips:
        return json.dumps({
            "error": "No stored utterances. Listen mode has to have been running.",
            "hint": "Clips are written to files/utt/ as wav + the recogniser's own transcript.",
        }, indent=1)

    if list_only:
        out = []
        for p in clips[:8]:
            out.append({
                "file": os.path.basename(p),
                "age_s": round(time.time() - os.path.getmtime(p), 1),
                "kb": round(os.path.getsize(p) / 1024.0, 1),
                "recogniser_text": _companion(p),
            })
        return json.dumps({"count": len(clips), "clips": out}, indent=1)

    idx = max(0, min(int(index or 0), len(clips) - 1))
    path = clips[idx]
    result = _transcribe(path)
    result.update({
        "file": os.path.basename(path),
        "age_s": round(time.time() - os.path.getmtime(path), 1),
        "recogniser_text": _companion(path),
        "available": len(clips),
    })
    return json.dumps(result, indent=1, ensure_ascii=False)


def _companion(wav_path):
    txt = wav_path[:-4] + ".txt"
    try:
        with open(txt) as fh:
            return fh.read().strip()
    except Exception:
        return None


def main(index: int = 0, list_only: bool = False) -> str:
    """Re-hear a stored utterance with Qwen ASR and compare it with what the phone's
    recogniser thought it heard. index 0 is the latest clip, 1 the one before; list_only
    just enumerates the stored clips without spending an API call."""
    out = _run(index, list_only)
    print(out)
    return out

"""Headless self-test harness. Drives the app's own classes from Python so a workflow can be
checked without touching the UI: the speech pipeline, ASR round-trip, news and location."""
import json
import os
import time

BASE = "/data/user/0/com.niki914.zafiro.evergrow.debug/files/"
VOICE_LOG = BASE + "voice_debug.log"


def _app():
    from com.chaquo.python import Python as CQ
    return CQ.getPlatform().getApplication()


def _log_tail_since(mark):
    try:
        with open(VOICE_LOG) as fh:
            lines = fh.read().splitlines()
    except Exception:
        return []
    return lines[mark:]


def _log_size():
    try:
        with open(VOICE_LOG) as fh:
            return len(fh.read().splitlines())
    except Exception:
        return 0


def check_audio(chunks=3, chunk_text="Test sentence number {}.", wait_s=30):
    """Speak several chunks and verify every one of them reached the speaker."""
    from com.niki914.zafiro.app.audio import VoiceReplySpeaker

    mark = _log_size()
    speaker = VoiceReplySpeaker(_app())
    started = time.time()
    for i in range(chunks):
        speaker.submit(chunk_text.format(i + 1))
    deadline = time.time() + wait_s
    played = []
    while time.time() < deadline:
        time.sleep(1.0)
        for line in _log_tail_since(mark):
            if "play: done" in line or "worker: played" in line:
                if line not in played:
                    played.append(line)
        if len(played) >= chunks:
            break
    return {
        "check": "audio",
        "chunks_submitted": chunks,
        "chunks_played": len(played),
        "elapsed_s": round(time.time() - started, 1),
        "pass": len(played) >= chunks,
    }


def check_asr():
    """Re-transcribe the newest stored utterance with Qwen and compare with the phone's text."""
    import base64
    import glob

    import requests

    clips = sorted(glob.glob(BASE + "utt/utt_*.wav"), key=os.path.getmtime, reverse=True)
    if not clips:
        return {"check": "asr", "pass": False, "note": "no stored utterances yet"}
    path = clips[0]
    with open(path, "rb") as fh:
        encoded = base64.b64encode(fh.read()).decode()
    key = open(BASE + "qwen_asr_key.txt").read().strip()
    body = {"model": "qwen3-asr-flash", "messages": [{"role": "user", "content": [
        {"type": "input_audio", "input_audio": {"data": "data:audio/wav;base64," + encoded}}]}]}
    r = requests.post("https://maas.qwencloudapi.com/compatible-mode/v1/chat/completions",
                      headers={"Authorization": "Bearer " + key}, json=body, timeout=60)
    ok = r.status_code == 200
    text = ""
    if ok:
        try:
            text = r.json()["choices"][0]["message"]["content"]
        except Exception:
            ok = False
    return {"check": "asr", "pass": ok and bool(text.strip()), "qwen_text": text[:120]}


def check_news():
    import xml.etree.ElementTree as ET

    import requests

    t0 = time.time()
    r = requests.get("https://news.google.com/rss/search?q=world%20news&hl=en-US&gl=US&ceid=US:en",
                     timeout=15, headers={"User-Agent": "Mozilla/5.0 (EverGrow)"})
    items = list(ET.fromstring(r.content).iter("item"))[:3]
    dated = [it for it in items if it.findtext("pubDate")]
    return {
        "check": "news",
        "pass": r.status_code == 200 and len(dated) >= 2,
        "items": len(items),
        "elapsed_s": round(time.time() - t0, 2),
    }


def check_location():
    from com.chaquo.python import Python as CQ

    ctx = _app()
    pm = ctx.getPackageManager()
    if pm.checkPermission("android.permission.ACCESS_FINE_LOCATION", ctx.getPackageName()) != 0:
        return {"check": "location", "pass": False, "note": "permission not granted"}
    lm = ctx.getSystemService("location")
    fixes = {}
    for provider in ("gps", "network", "fused"):
        try:
            loc = lm.getLastKnownLocation(provider)
        except Exception:
            continue
        if loc is not None:
            fixes[provider] = {"lat": round(loc.getLatitude(), 5), "lon": round(loc.getLongitude(), 5),
                               "accuracy_m": round(loc.getAccuracy(), 1)}
    return {"check": "location", "pass": bool(fixes), "fixes": fixes}


CHECKS = {"audio": check_audio, "asr": check_asr, "news": check_news, "location": check_location}


def main(suite: str = "audio") -> str:
    """Run headless checks without the UI. suite is a comma list of
    audio, asr, news, location, or "all"."""
    names = [s.strip() for s in (suite or "audio").split(",") if s.strip()]
    if names == ["all"]:
        names = ["audio", "asr", "news", "location"]
    results = []
    for name in names:
        fn = CHECKS.get(name)
        if fn is None:
            results.append({"check": name, "pass": False, "note": "unknown check"})
            continue
        try:
            results.append(fn())
        except Exception as exc:
            results.append({"check": name, "pass": False, "error": type(exc).__name__ + ": " + str(exc)[:120]})
    summary = {
        "passed": sum(1 for r in results if r.get("pass")),
        "total": len(results),
        "results": results,
    }
    out = json.dumps(summary, indent=1)
    print(out)
    return out

"""Watch the Zafiro ecosystem for anything new worth leveraging: upstream commits we lack,
commits in other forks touching voice/speech/navigation, and new GitHub projects in our space.
Keeps state so a second run only reports what changed."""
import json
import os
import re
import time

import requests

BASE = "/data/user/0/com.niki914.zafiro.evergrow.debug/files/"
TOKEN_FILE = BASE + "tool_output/evergrow/.token"
STATE_FILE = BASE + "tool_output/evergrow/repo_watch_state.json"
API = "https://api.github.com"
UPSTREAM = "niki914/zafiro"
OURS = "donal100/Evergrow"

KEYWORDS = re.compile(
    r"voice|speech|tts|stt|asr|listen|wake|navigat|route|gps|location|camera|vision", re.I)

SEARCHES = [
    "android voice assistant llm stars:>50",
    "always listening android agent",
    "android ai agent voice tool calling",
]


def _headers():
    with open(TOKEN_FILE) as fh:
        return {"Authorization": "Bearer " + fh.read().strip(),
                "Accept": "application/vnd.github+json"}


def _get(path, **params):
    r = requests.get(API + path, headers=_headers(), params=params, timeout=40)
    if r.status_code != 200:
        raise RuntimeError("%s -> HTTP %s" % (path, r.status_code))
    return r.json()


def _load_state():
    try:
        with open(STATE_FILE) as fh:
            return json.load(fh)
    except Exception:
        return {"seen_upstream": [], "seen_repos": [], "first_run": True}


def _save_state(state):
    os.makedirs(os.path.dirname(STATE_FILE), exist_ok=True)
    with open(STATE_FILE, "w") as fh:
        json.dump(state, fh)


def _upstream_commits(state):
    cs = _get(f"/repos/{UPSTREAM}/commits", per_page=30, sha="main")
    seen = set(state.get("seen_upstream", []))
    fresh = []
    for c in cs:
        sha = c["sha"]
        if sha in seen:
            continue
        fresh.append({"sha": sha[:7], "date": c["commit"]["author"]["date"][:10],
                      "msg": c["commit"]["message"].splitlines()[0][:100]})
    state["seen_upstream"] = [c["sha"] for c in cs][:60]
    behind = None
    try:
        # 跨 fork 比较要走上游仓库：拿我们 main 的 sha，问上游「落后多少」
        ours = _get(f"/repos/{OURS}/git/ref/heads/main")
        sha = ours["object"]["sha"]
        cmp_ = _get(f"/repos/{UPSTREAM}/compare/{sha}...main")
        behind = cmp_.get("behind_by")
    except Exception as exc:
        behind = "unknown: " + type(exc).__name__
    return {"behind_by": behind, "new_commits": fresh}


def _fork_scan():
    forks = _get(f"/repos/{UPSTREAM}/forks", per_page=20, sort="newest")
    hits = []
    for f in forks[:10]:
        name = f["full_name"]
        if name.lower().startswith("donal100/"):
            continue
        try:
            cs = _get(f"/repos/{name}/commits", per_page=15)
        except Exception:
            continue
        if not isinstance(cs, list):
            continue
        matched = [c["commit"]["message"].splitlines()[0][:90]
                   for c in cs if KEYWORDS.search(c["commit"]["message"].splitlines()[0])]
        if matched:
            hits.append({"fork": name, "pushed": f["pushed_at"][:10], "commits": matched[:3]})
    return hits


def _repo_search(state):
    seen = set(state.get("seen_repos", []))
    found = []
    cutoff = time.strftime("%Y-%m-%d", time.gmtime(time.time() - 21 * 86400))
    for q in SEARCHES:
        try:
            js = _get("/search/repositories", q=q, sort="stars", order="desc", per_page=8)
        except Exception:
            continue
        for item in js.get("items", []):
            name = item["full_name"]
            if name in seen or item["pushed_at"][:10] < cutoff:
                continue
            seen.add(name)
            found.append({"repo": name, "stars": item["stargazers_count"],
                          "pushed": item["pushed_at"][:10],
                          "desc": (item["description"] or "")[:90]})
        time.sleep(2)
    state["seen_repos"] = list(seen)[-200:]
    return found


def _run(scope):
    state = _load_state()
    out = {}
    if scope in ("all", "upstream"):
        out["upstream"] = _upstream_commits(state)
    if scope in ("all", "forks"):
        out["forks_with_relevant_commits"] = _fork_scan()
    if scope in ("all", "repos"):
        out["new_repos"] = _repo_search(state)
    out["first_run"] = bool(state.get("first_run"))
    state["first_run"] = False
    _save_state(state)
    return out


def main(scope: str = "all") -> str:
    """Check the ecosystem for anything worth leveraging: scope=upstream (commits we lack),
    forks (other forks' voice/nav commits), repos (new GitHub projects), or all."""
    out = json.dumps(_run(scope), indent=1, ensure_ascii=False)
    print(out)
    return out

"""Walking navigation for the agent: geocode a destination, fetch a foot route, then answer
'where next' with the next turn, the distance to it, and whether you are facing the right way."""
import json
import math
import os
import time

import requests

BASE = "/data/user/0/com.niki914.zafiro.evergrow.debug/files/"
ROUTE_FILE = BASE + "tool_output/evergrow/nav_route.json"
UA = {"User-Agent": "EverGrow-agent/1.0 (personal navigation)"}
ROUTES_URL = "https://routes.googleapis.com/directions/v2:computeRoutes"
MAPS_KEY_FILE = BASE + "google_maps_key.txt"
ROUTE_FIELDS = ("routes.duration,routes.distanceMeters,"
                "routes.legs.steps.distanceMeters,routes.legs.steps.navigationInstruction,"
                "routes.legs.steps.startLocation.latLng")
NOMINATIM = "https://nominatim.openstreetmap.org/search"


_watch = {"thread": None, "stop": False}


def _ctx():
    from com.chaquo.python import Python as CQ
    return CQ.getPlatform().getApplication()


def _gps():
    ctx = _ctx()
    lm = ctx.getSystemService("location")
    best = None
    for provider in ("gps", "fused", "network"):
        try:
            loc = lm.getLastKnownLocation(provider)
        except Exception:
            continue
        if loc is not None and (best is None or loc.getTime() > best.getTime()):
            best = loc
    if best is None:
        return None
    return {"lat": best.getLatitude(), "lon": best.getLongitude(),
            "acc": round(best.getAccuracy(), 1) if best.hasAccuracy() else None,
            "bearing": round(best.getBearing(), 1) if best.hasBearing() else None,
            "speed": round(best.getSpeed(), 2) if best.hasSpeed() else None,
            "age_s": round((time.time() * 1000 - best.getTime()) / 1000, 1)}


def _haversine(a, b):
    r = 6371000.0
    p1, p2 = math.radians(a["lat"]), math.radians(b["lat"])
    dp = p2 - p1
    dl = math.radians(b["lon"] - a["lon"])
    h = math.sin(dp / 2) ** 2 + math.cos(p1) * math.cos(p2) * math.sin(dl / 2) ** 2
    return 2 * r * math.asin(min(1.0, math.sqrt(h)))


def _bearing(a, b):
    lat1, lat2 = math.radians(a["lat"]), math.radians(b["lat"])
    dl = math.radians(b["lon"] - a["lon"])
    y = math.sin(dl) * math.cos(lat2)
    x = math.cos(lat1) * math.sin(lat2) - math.sin(lat1) * math.cos(lat2) * math.cos(dl)
    return (math.degrees(math.atan2(y, x)) + 360) % 360


def _geocode(query):
    r = requests.get(NOMINATIM, params={"q": query, "format": "jsonv2", "limit": 1,
                                        "accept-language": "en"}, headers=UA, timeout=25)
    if r.status_code != 200 or not r.json():
        return None
    hit = r.json()[0]
    return {"lat": float(hit["lat"]), "lon": float(hit["lon"]),
            "name": (hit.get("display_name") or query).split(",")[0],
            "full": (hit.get("display_name") or "")[:120]}


def _route(start, end):
    """Google Routes，步行模式。比 OSM 步行路由强的地方：每一步都带路名和整句指令。"""
    with open(MAPS_KEY_FILE) as fh:
        key = fh.read().strip()
    body = {
        "origin": {"location": {"latLng": {"latitude": start["lat"], "longitude": start["lon"]}}},
        "destination": {"location": {"latLng": {"latitude": end["lat"], "longitude": end["lon"]}}},
        "travelMode": "WALK", "languageCode": "en", "units": "METRIC",
    }
    r = requests.post(ROUTES_URL, headers={"X-Goog-Api-Key": key, "Content-Type": "application/json",
                                           "X-Goog-FieldMask": ROUTE_FIELDS}, json=body, timeout=40)
    if r.status_code != 200:
        raise RuntimeError("routing HTTP %s: %s" % (r.status_code, r.text[:120]))
    routes = r.json().get("routes") or []
    if not routes:
        raise RuntimeError("no walking route found")
    rt = routes[0]
    steps = []
    for s in rt["legs"][0]["steps"]:
        latlng = (s.get("startLocation") or {}).get("latLng") or {}
        instr = (s.get("navigationInstruction") or {}).get("instructions") or ""
        # Google 会在指令后面换行附一句「Restricted usage road」之类，念出来很怪
        instr = instr.split("\n")[0].strip().rstrip(".")
        steps.append({"instruction": instr, "distance": round(s.get("distanceMeters", 0)),
                      "lat": latlng.get("latitude"), "lon": latlng.get("longitude")})
    return {"distance_m": round(rt["distanceMeters"]),
            "duration_min": round(int(rt["duration"].rstrip("s")) / 60, 1),
            "steps": steps}


def _save(route, dest):
    os.makedirs(os.path.dirname(ROUTE_FILE), exist_ok=True)
    payload = {"created": time.time(), "destination": dest, "route": route}
    with open(ROUTE_FILE, "w") as fh:
        json.dump(payload, fh)


def _load():
    try:
        with open(ROUTE_FILE) as fh:
            return json.load(fh)
    except Exception:
        return None


def _turn_phrase(step):
    if step.get("instruction"):
        return step["instruction"]
    kind = (step.get("type") or "").lower()
    mod = (step.get("modifier") or "").replace("-", " ")
    onto = (" onto " + step["name"]) if step.get("name") else ""
    if kind in ("depart", "start"):
        return "Start walking" + onto
    if kind in ("arrive", "end"):
        return "Arrive at your destination"
    if mod.startswith("slight"):
        return ("Bear " + mod.replace("slight ", "") + onto).strip()
    if mod in ("left", "right"):
        return "Turn " + mod + onto
    if mod == "straight":
        return "Keep straight" + onto
    return ("Continue" + onto).strip()


def _start(destination):
    here = _gps()
    if here is None:
        return {"error": "No GPS fix yet."}
    dest = _geocode(destination)
    if dest is None:
        return {"error": "Could not find '%s' on the map." % destination}
    route = _route(here, dest)
    _save(route, dest)
    first = next((s for s in route["steps"][1:] if s["lat"] is not None), None)
    out = {
        "destination": dest["name"], "full_name": dest["full"],
        "distance_m": route["distance_m"], "duration_min": route["duration_min"],
        "steps": len(route["steps"]),
        "first_move": _turn_phrase(first) if first else None,
        "first_in_m": round(_haversine(here, first)) if first else None,
        "gps_accuracy_m": here["acc"],
    }
    print(json.dumps(out, indent=1))
    return out


def _status():
    saved = _load()
    if not saved:
        return {"error": "No active route. Say where you want to go first."}
    here = _gps()
    if here is None:
        return {"error": "No GPS fix."}
    steps = [s for s in saved["route"]["steps"] if s["lat"] is not None]
    remaining_from = 0
    for i, s in enumerate(steps):
        if _haversine(here, s) > 20:
            remaining_from = i
            break
    ahead = steps[remaining_from:]
    to_go = sum(s["distance"] for s in ahead)
    nxt = ahead[0] if ahead else None
    out = {
        "destination": saved["destination"]["name"],
        "distance_to_turn_m": round(_haversine(here, nxt)) if nxt else None,
        "instruction": _turn_phrase(nxt) if nxt else "Arrive at your destination",
        "then": _turn_phrase(ahead[1]) if len(ahead) > 1 else None,
        "remaining_m": to_go,
        "gps_accuracy_m": here["acc"],
    }
    # 方向检查：朝向下一个转弯点的方位 vs 手机报告的航向
    if nxt is not None:
        want = _bearing(here, nxt)
        have = here["bearing"]
        out["want_bearing"] = round(want)
        out["your_bearing"] = have
        if have is not None and here.get("speed", 0) and here["speed"] > 0.4:
            diff = abs((want - have + 180) % 360 - 180)
            out["heading_delta"] = round(diff)
            out["on_track"] = diff < 50
            out["comment"] = ("You're heading the right way." if diff < 50
                              else ("You're facing about %d degrees off — turn around." % round(diff)))
        else:
            out["comment"] = "Not moving fast enough to tell your heading yet."
    print(json.dumps(out, indent=1))
    return out


def _stop():
    try:
        os.remove(ROUTE_FILE)
    except Exception:
        pass
    print(json.dumps({"stopped": True}))
    return {"stopped": True}


def _speak(text):
    """用应用自己的 TTS 念一句（在后台线程里跑，必须整体包住异常）。"""
    try:
        from com.chaquo.python import Python as CQ
        from com.niki914.zafiro.app.audio import SpeechOutput
        sp = SpeechOutput(CQ.getPlatform().getApplication())
        time.sleep(1.2)
        sp.speak(text)
        time.sleep(3.5)
        sp.release()
    except Exception:
        pass


def _agent_is_talking():
    """最近 8 秒内 agent 正在念话/合成，就别插嘴。"""
    try:
        with open(BASE + "voice_debug.log") as fh:
            tail = fh.read().splitlines()[-6:]
        now_ms = time.time() * 1000
        for line in tail:
            parts = line.split("  ", 1)
            if len(parts) != 2:
                continue
            if any(k in parts[1] for k in ("submit chars", "synth: ready", "play: done")):
                if now_ms - float(parts[0]) < 8000:
                    return True
    except Exception:
        pass
    return False


def _watch_loop():
    """每 5 秒看一次：快到了就提前报路口，走错了就提醒。"""
    off_count = 0
    last_nudge = 0.0
    announced = -1          # 已经报过第几个转弯（按步骤序号）
    arrived = False
    while not _watch["stop"]:
        try:
            time.sleep(5)
            if _watch["stop"]:
                break
            saved = _load()
            if not saved:
                break
            here = _gps()
            if here is None:
                continue
            steps = [s for s in saved["route"]["steps"] if s.get("lat") is not None]

            # 找下一个还没走到的转弯
            idx, nxt = None, None
            for i, s in enumerate(steps):
                if _haversine(here, s) > 18:
                    idx, nxt = i, s
                    break

            if nxt is None:
                if not arrived and not _agent_is_talking():
                    arrived = True
                    _speak("You have arrived at " + saved["destination"]["name"] + ".")
                continue

            dist = round(_haversine(here, nxt))

            # 提前报路口：60 米内、且这一步还没报过
            if dist <= 60 and idx != announced and not _agent_is_talking():
                announced = idx
                phrase = nxt.get("instruction") or "Carry on"
                _speak("In %d metres, %s." % (dist, phrase[0].lower() + phrase[1:]))

            # 方向检查（只有真的在走的时候才有航向）
            want = _bearing(here, nxt)
            have = here.get("bearing")
            if have is not None and (here.get("speed") or 0) >= 0.5:
                diff = abs((want - have + 180) % 360 - 180)
                off_count = off_count + 1 if diff > 60 else 0
                if off_count >= 2 and time.time() - last_nudge > 45 and not _agent_is_talking():
                    last_nudge = time.time()
                    off_count = 0
                    _speak("Hold on — you're heading the wrong way.")
        except Exception:
            time.sleep(5)
    _watch["thread"] = None


def _start_watch():
    if _watch["thread"] is not None:
        return {"watching": True, "note": "already running"}
    if _load() is None:
        return {"error": "Start a route first."}
    import threading
    _watch["stop"] = False
    th = threading.Thread(target=_watch_loop, daemon=True)
    _watch["thread"] = th
    th.start()
    return {"watching": True, "checks_every_s": 10, "nudge_cooldown_s": 45}


def _stop_watch():
    _watch["stop"] = True
    _watch["thread"] = None
    return {"watching": False}


def main(action: str = "status", destination: str = "") -> str:
    """Walking navigation. action=start needs a destination; action=status reports the next
    turn, distance and heading check; action=watch starts background wrong-way nudges;
    action=unwatch or stop ends guidance."""
    if action == "start":
        if not destination.strip():
            print(json.dumps({"error": "destination required"}))
            return "error"
        return json.dumps(_start(destination))
    if action == "stop":
        _stop_watch()
        return json.dumps(_stop())
    if action in ("watch", "guide"):
        return json.dumps(_start_watch())
    if action == "unwatch":
        return json.dumps(_stop_watch())
    return json.dumps(_status())

tools.description:
Walking navigation. action=start needs a destination (place name or 'lat,lon');
action=status says the next turn, distance, and whether you are facing the right way;
action=stop clears the route.

tools.code:
"""Compare ways to get somewhere: transit, walking and driving via Google Routes API, with a
taxi fare estimate. Answers 'what is the best way to get to X'."""
import json
import re
import time

import requests

BASE = "/data/user/0/com.niki914.zafiro.evergrow.debug/files/"
KEY_FILE = BASE + "google_maps_key.txt"
URL = "https://routes.googleapis.com/directions/v2:computeRoutes"
FIELDS = ("routes.duration,routes.distanceMeters,"
          "routes.legs.steps.travelMode,routes.legs.steps.distanceMeters,"
          "routes.legs.steps.navigationInstruction,"
          "routes.legs.steps.transitDetails.transitLine.name,"
          "routes.legs.steps.transitDetails.transitLine.nameShort,"
          "routes.legs.steps.transitDetails.transitLine.vehicle.type,"
          "routes.legs.steps.transitDetails.stopDetails.departureStop.name,"
          "routes.legs.steps.transitDetails.stopDetails.arrivalStop.name")

# 香港市区的士：起表 HK$29（首 2 公里），之后约 HK$2.1 / 200 米；隧道费另计
TAXI_FLAG = 29.0
TAXI_PER_KM = 10.5



MTR_LINES = {
    "Tuen Ma Line": "TML", "Tsuen Wan Line": "TWL", "Tung Chung Line": "TCL",
    "Island Line": "ISL", "Kwun Tong Line": "KTL", "East Rail Line": "EAL",
    "South Island Line": "SIL", "Tseung Kwan O Line": "TKO",
    "Airport Express": "AEL", "Disneyland Resort Line": "DRL",
}
STATIONS = {
    "tin shui wai": "TIS", "long ping": "LOP", "yuen long": "YUL", "kam sheung road": "KSR",
    "tsuen wan west": "TWW", "mei foo": "MEF", "nam cheong": "NAC", "olympic": "OLY",
    "kowloon": "KOW", "hong kong": "HOK", "central": "CEN", "admiralty": "ADM",
    "wan chai": "WAC", "causeway bay": "CAB", "tin hau": "TIH", "fortress hill": "FOH",
    "north point": "NOP", "quarry bay": "QUB", "tai koo": "TAK", "sai wan ho": "SWH",
    "shau kei wan": "SKW", "heng fa chuen": "HFC", "chai wan": "CHW",
    "austin": "AUS", "east tsim sha tsui": "ETS", "hung hom": "HUH",
    "mong kok east": "MKK", "kowloon tong": "KOT", "tai wai": "TAW", "sha tin": "SHT",
    "university": "UNI", "sheung shui": "SHS", "tsing yi": "TSY", "sunny bay": "SUN",
    "tung chung": "TUC", "prince edward": "PRE", "mong kok": "MOK", "yau ma tei": "YMT",
    "jordan": "JOR", "tsim sha tsui": "TST", "sheung wan": "SHW", "sai ying pun": "SYP",
    "hkU": "HKU", "kennedy town": "KET", "whampoa": "WHA", "ho man tin": "HOM",
    "to kwa wan": "TKW", "sung wong toi": "SUW", "kai tak": "KAT", "diamond hill": "DIH",
    "kowloon bay": "KOB", "ngau tau kok": "NTK", "kwun tong": "KWT", "lam tin": "LAT",
    "yau tong": "YAT", "tiu keng leng": "TIK", "tseung kwan o": "TKO", "po lam": "POA",
}


def _station_code(name):
    """'Nam Cheong Station' -> NAC；容忍 Glue 词与多余后缀。"""
    s = (name or "").strip().lower()
    for junk in (" station", " stop", " terminus", " mtr", " (west)", " (east)"):
        s = s.replace(junk, "")
    s = s.strip()
    if s in STATIONS:
        return STATIONS[s]
    for key, code in STATIONS.items():
        if key and (key in s or s in key) and len(s) > 4:
            return code
    return None


def _mtr_next(line_name, station_name):
    """下一班车还有几分钟（MTR 官方实时）。"""
    line = MTR_LINES.get(line_name)
    sta = _station_code(station_name)
    if not line or not sta:
        return None
    try:
        r = requests.get("https://rt.data.gov.hk/v1/transport/mtr/getSchedule.php",
                         params={"line": line, "sta": sta, "lang": "en"},
                         headers={"User-Agent": "EverGrow-agent/1.0"}, timeout=20)
        j = r.json()
        key = line + "-" + sta
        block = (j.get("data") or {}).get(key) or {}
        # 两个方向都给：只有目的地才知道该坐哪个方向，光挑「最近一班」会坐反
        directions = {}
        for direction in ("UP", "DOWN"):
            best = None
            for tr in (block.get(direction) or []):
                if tr.get("valid") != "Y":
                    continue
                mins = tr.get("ttnt")
                if mins is None:
                    continue
                m = int(float(mins))
                if best is None or m < best["minutes"]:
                    best = {"minutes": m, "towards": tr.get("dest")}
            if best:
                directions[direction] = best
        if directions:
            return {"station": sta, "line": line, "directions": directions}
    except Exception:
        return None
    return None



STOP_CACHE = BASE + "tool_output/evergrow/bus_stops.json"


def _stop_cache():
    try:
        with open(STOP_CACHE) as fh:
            return json.load(fh)
    except Exception:
        return {}


def _save_stop_cache(cache):
    try:
        with open(STOP_CACHE, "w") as fh:
            json.dump(cache, fh)
    except Exception:
        pass


def _distance(lat1, lon1, lat2, lon2):
    import math
    R = 6371000.0
    p1, p2 = math.radians(lat1), math.radians(lat2)
    dp = p2 - p1
    dl = math.radians(lon2 - lon1)
    h = math.sin(dp / 2) ** 2 + math.cos(p1) * math.cos(p2) * math.sin(dl / 2) ** 2
    return 2 * R * math.asin(min(1.0, math.sqrt(h)))


def _stop_coords(operator, stop_id, cache):
    k = operator + ":" + stop_id
    if k in cache:
        return cache[k]
    try:
        if operator == "CTB":
            js = requests.get("https://rt.data.gov.hk/v2/transport/citybus/stop/" + stop_id,
                              headers={"User-Agent": "EverGrow-agent/1.0"}, timeout=15).json()
        else:
            js = requests.get("https://data.etabus.gov.hk/v1/transport/kmb/stop/" + stop_id,
                              headers={"User-Agent": "EverGrow-agent/1.0"}, timeout=15).json()
        data = js.get("data") or {}
        if data:
            entry = {"lat": float(data["lat"]), "lon": float(data.get("long") or data.get("lon")),
                     "name": data.get("name_en") or data.get("name_tc") or ""}
            cache[k] = entry
            return entry
    except Exception:
        return None
    return None


def _bus_eta(route, here):
    """路线号 -> 最近的站 -> 下一班几分钟。距离靠坐标判断，不靠站名。"""
    if not route or not route.strip().isdigit():
        return None
    route = route.strip()
    cache = _stop_cache()
    plans = [("CTB", "https://rt.data.gov.hk/v2/transport/citybus/route-stop/CTB/%s/outbound"),
             ("CTB", "https://rt.data.gov.hk/v2/transport/citybus/route-stop/CTB/%s/inbound"),
             ("KMB", "https://data.etabus.gov.hk/v1/transport/kmb/route-stop/%s/outbound/1"),
             ("KMB", "https://data.etabus.gov.hk/v1/transport/kmb/route-stop/%s/inbound/1")]
    for operator, tpl in plans:
        try:
            js = requests.get(tpl % route, headers={"User-Agent": "EverGrow-agent/1.0"}, timeout=20).json()
            stops = js.get("data") or []
        except Exception:
            continue
        if not stops:
            continue
        best = None
        for item in stops[:18]:
            sid = item.get("stop")
            info = _stop_coords(operator, sid, cache)
            if not info:
                continue
            dm = _distance(here["lat"], here["lon"], info["lat"], info["lon"])
            if best is None or dm < best[0]:
                best = (round(dm), sid, info["name"])
        if best:
            _save_stop_cache(cache)
            sid = best[1]
            try:
                if operator == "CTB":
                    url = "https://rt.data.gov.hk/v2/transport/citybus/eta/CTB/%s/%s" % (sid, route)
                else:
                    url = "https://data.etabus.gov.hk/v1/transport/kmb/eta/%s/%s/1" % (sid, route)
                arr = requests.get(url, headers={"User-Agent": "EverGrow-agent/1.0"}, timeout=20).json().get("data") or []
            except Exception:
                arr = []
            minutes = None
            for e in arr:
                iso = e.get("eta")
                if not iso:
                    continue
                try:
                    t = time.mktime(time.strptime(iso[:19], "%Y-%m-%dT%H:%M:%S"))
                    mins = max(0, round((t - time.time()) / 60))
                    if minutes is None or mins < minutes:
                        minutes = mins
                except Exception:
                    continue
            return {"operator": operator, "stop": best[2], "stop_id": sid,
                    "walk_m": best[0], "next_minutes": minutes}
    return None


def _enrich(options):
    """给每个轨道段补上「下一班还有几分钟」。"""
    for opt in options:
        for leg in opt.get("legs", []):
            if leg.get("mode") != "transit":
                continue
            line = leg.get("line") or ""
            if line in MTR_LINES:
                leg["realtime"] = _mtr_next(line, leg.get("from"))
            elif line[:1].isdigit():
                here = _here()
                latlng = (here or {}).get("location", {}).get("latLng", {})
                if latlng:
                    leg["realtime"] = _bus_eta(line, {"lat": latlng.get("latitude"),
                                                      "lon": latlng.get("longitude")})
    return options


def _key():
    with open(KEY_FILE) as fh:
        return fh.read().strip()


def _here():
    from com.chaquo.python import Python as CQ
    lm = CQ.getPlatform().getApplication().getSystemService("location")
    best = None
    for provider in ("gps", "fused", "network"):
        try:
            loc = lm.getLastKnownLocation(provider)
        except Exception:
            continue
        if loc is not None and (best is None or loc.getTime() > best.getTime()):
            best = loc
    if best is None:
        return None
    return {"location": {"latLng": {"latitude": best.getLatitude(),
                                    "longitude": best.getLongitude()}}}


def _query(origin, destination, mode, alternatives=True):
    body = {"origin": origin,
            "destination": {"address": destination},
            "travelMode": mode, "languageCode": "en", "units": "METRIC"}
    if alternatives and mode == "TRANSIT":
        body["computeAlternativeRoutes"] = True
    if mode == "DRIVE":
        body["routingPreference"] = "TRAFFIC_AWARE"
    r = requests.post(URL, headers={"X-Goog-Api-Key": _key(), "Content-Type": "application/json",
                                    "X-Goog-FieldMask": FIELDS}, json=body, timeout=40)
    if r.status_code != 200:
        return {"error": "HTTP %s: %s" % (r.status_code, r.text[:150])}
    routes = r.json().get("routes") or []
    out = []
    for rt in routes:
        mins = round(int(rt["duration"].rstrip("s")) / 60)
        km = round(rt["distanceMeters"] / 1000, 1)
        legs = []
        for step in rt["legs"][0]["steps"]:
            td = step.get("transitDetails")
            if td:
                tl = td.get("transitLine") or {}
                line = tl.get("nameShort") or tl.get("name") or "transit"
                legs.append({"mode": "transit", "line": line,
                             "from": (td.get("stopDetails") or {}).get("departureStop", {}).get("name"),
                             "to": (td.get("stopDetails") or {}).get("arrivalStop", {}).get("name")})
            elif step["travelMode"] == "WALKING":
                legs.append({"mode": "walk", "m": step.get("distanceMeters", 0)})
        out.append({"mode": mode, "minutes": mins, "km": km, "legs": legs})
    return {"options": out}


def _summarise(opt):
    if opt["mode"] == "TRANSIT":
        lines = [l["line"] for l in opt["legs"] if l["mode"] == "transit"]
        walk_m = sum(l.get("m", 0) for l in opt["legs"] if l["mode"] == "walk")
        return {"summary": ("%d min by %s" % (opt["minutes"], " then ".join(lines))),
                "changes": max(0, len(lines) - 1), "walk_m": walk_m}
    if opt["mode"] == "DRIVE":
        fare = round(TAXI_FLAG + max(0.0, opt["km"] - 2) * TAXI_PER_KM)
        return {"summary": "%d min driving, %.1f km" % (opt["minutes"], opt["km"]),
                "taxi_fare_hkd_approx": fare}
    return {"summary": "%d min walking, %.1f km" % (opt["minutes"], opt["km"])}


def _parse_latlng(text):
    """'22.4583,114.0029' -> Routes 要的 latLng 结构。

    以前把坐标当 address 传，Google 解析不出来就静默返回 0 条路线，
    于是「查路线」永远得到空列表（而且不报错，最难查的那种）。
    """
    m = re.match(r"^\s*(-?\d+(?:\.\d+)?)\s*,\s*(-?\d+(?:\.\d+)?)\s*$", text or "")
    if not m:
        return None
    return {"location": {"latLng": {"latitude": float(m.group(1)), "longitude": float(m.group(2))}}}


def _plan(destination, origin_text):
    _t0 = time.time()
    parsed = _parse_latlng(origin_text)
    if parsed is not None:
        origin = parsed
    elif origin_text.strip():
        origin = {"address": origin_text}
    else:
        origin = _here()
    if origin is None:
        return {"error": "No GPS fix; give an origin instead."}
    # 并行查三种方式：串行时每次都是独立的网络往返，加起来就是三倍延迟
    import concurrent.futures as _cf
    def _one(mode):
        try:
            return mode, _query(origin, destination, mode)
        except Exception as exc:
            return mode, {"error": type(exc).__name__ + ": " + str(exc)[:80]}
    results = {}
    with _cf.ThreadPoolExecutor(max_workers=3) as pool:
        for mode, res in pool.map(_one, ("TRANSIT", "DRIVE", "WALK")):
            results[mode] = res

    options = []
    for mode, res in results.items():
        for opt in (res.get("options") or [])[:2]:
            merged = dict(opt)
            merged.update(_summarise(opt))
            options.append(merged)
    # 走路超过 45 分钟的方案不叫「方案」，别塞给用户
    options = [o for o in options if not (o["mode"] == "WALK" and o["minutes"] > 45)]
    options.sort(key=lambda o: o["minutes"])
    _enrich(options)
    errors = {m: r["error"] for m, r in results.items() if isinstance(r, dict) and r.get("error")}
    out = {"destination": destination, "options": options[:4],
            "note": "Times from Google Routes; taxi fare is an estimate excluding tunnels."}
    if errors:
        out["errors"] = errors
    out["fetch_s"] = round(time.time() - _t0, 2)
    if not options:
        out["hint"] = "No route found for any mode; check the destination name."
    return out
    return {"destination": destination, "options": options[:4],
            "note": "Times from Google Routes; taxi fare is an estimate excluding tunnels."}


def main(destination: str = "", origin: str = "") -> str:
    """Compare transit, driving and walking to a destination and return the options ranked by
    time, with a taxi fare estimate for driving."""
    if not destination.strip():
        out = json.dumps({"error": "destination required"})
        print(out)
        return out
    out = json.dumps(_plan(destination, origin), indent=1, ensure_ascii=False)
    print(out)
    return out

"""Hear what was actually said in the last few minutes, from the app's rolling 5-minute audio
archive. Use when listen mode missed, clipped or misheard something: extract the window and
run it through Qwen ASR, independently of the phone's recogniser."""
import base64
import glob
import json
import os
import time
import wave

import requests

BASE = "/data/user/0/com.niki914.zafiro.evergrow.debug/files/"
ARCHIVE = BASE + "voice_ring/"
ENDPOINT = "https://maas.qwencloudapi.com/compatible-mode/v1/chat/completions"
MODEL = "qwen3-asr-flash"


def _key():
    with open(BASE + "qwen_asr_key.txt") as fh:
        return fh.read().strip()


def _segments():
    files = []
    for p in glob.glob(ARCHIVE + "seg_*.wav"):
        stamp = os.path.basename(p)[4:-4].split(".")[0]
        try:
            files.append((int(stamp), p))
        except ValueError:
            continue
    files.sort()
    return files


def _describe(files):
    if not files:
        return None
    oldest, newest = files[0][0], files[-1][0]
    return {
        "segments": len(files),
        "newest_age_s": round(time.time() - newest / 1000.0, 1),
        "span_s": round((newest - oldest) / 1000.0, 1),
    }


def _window(files, seconds):
    """取最后 N 秒的采样，拼成一个 wav。"""
    if not files:
        return None
    chunks = []
    total = 0
    need = int(seconds * 16000)
    for _, path in reversed(files):
        try:
            with wave.open(path) as w:
                frames = w.readframes(w.getnframes())
        except Exception:
            continue
        chunks.append(frames)
        total += len(frames) // 2
        if total >= need:
            break
    if not chunks:
        return None
    pcm = b"".join(reversed(chunks))
    # 裁到「最后 N 秒」：多出来的从头部砍掉
    if total > need:
        pcm = pcm[-need * 2:]
    out = BASE + "tool_output/voice_window.wav"
    os.makedirs(os.path.dirname(out), exist_ok=True)
    with wave.open(out, "wb") as w:
        w.setnchannels(1); w.setsampwidth(2); w.setframerate(16000)
        w.writeframes(pcm)
    return out, round(len(pcm) / 2 / 16000.0, 2)


def _transcribe(path):
    with open(path, "rb") as fh:
        encoded = base64.b64encode(fh.read()).decode()
    body = {"model": MODEL, "messages": [{"role": "user", "content": [
        {"type": "input_audio", "input_audio": {"data": "data:audio/wav;base64," + encoded}}]}]}
    r = requests.post(ENDPOINT, headers={"Authorization": "Bearer " + _key()}, json=body, timeout=90)
    if r.status_code != 200:
        return {"error": "HTTP %s" % r.status_code, "body": r.text[:200]}
    try:
        return {"text": r.json()["choices"][0]["message"]["content"]}
    except Exception:
        return {"error": "unexpected response", "body": r.text[:200]}


def main(seconds: int = 60, list_only: bool = False) -> str:
    """Hear what was actually said in the last few minutes, from the app's rolling 5-minute audio
    archive. Use when listen mode missed, clipped or misheard something: extract the window and
    run it through Qwen ASR, independently of the phone's recogniser."""
    files = _segments()
    info = _describe(files)
    if list_only:
        out = json.dumps({"archive": info, "dir": ARCHIVE}, indent=1)
        print(out)
        return out
    if not info:
        out = json.dumps({
            "error": "The rolling archive is empty.",
            "hint": "It is written only while listen mode runs, and needs a build that includes it.",
        }, indent=1)
        print(out)
        return out
    window = _window(files, max(5, int(seconds)))
    if not window:
        out = json.dumps({"error": "Could not read any segment.", "archive": info}, indent=1)
        print(out)
        return out
    path, got = window
    result = _transcribe(path)
    result.update({"window_s": got, "archive": info, "file": path})
    out = json.dumps(result, indent=1, ensure_ascii=False)
    print(out)
    return out

"""Real Google Search results via SerpApi, including news and an AI overview. Use this for
web search when result quality matters: it returns Google's own ranking, snippets, top
stories and related searches, unlike the scraped Chinese engines."""
import json
import os
import time

import requests

BASE = "/data/user/0/com.niki914.zafiro.evergrow.debug/files/"
KEY_FILE = BASE + "tool_output/serpapi/.token"
ENDPOINT = "https://serpapi.com/search.json"


def _key():
    with open(KEY_FILE) as fh:
        return fh.read().strip()


def _search(query, num=6, kind="web", hl="en", gl="hk", location=None):
    params = {"q": query, "api_key": _key(), "num": num, "hl": hl, "gl": gl}
    if kind == "news":
        params["tbm"] = "nws"
    if kind == "images":
        params["tbm"] = "isch"
    if location:
        params["location"] = location
    t0 = time.time()
    r = requests.get(ENDPOINT, params=params, timeout=60)
    elapsed = round(time.time() - t0, 2)
    if r.status_code != 200:
        try:
            err = r.json().get("error")
        except Exception:
            err = r.text[:200]
        return {"error": "HTTP %s: %s" % (r.status_code, err), "fetch_s": elapsed}
    j = r.json()
    out = {"query": query, "fetch_s": elapsed, "results": []}
    for item in (j.get("organic_results") or [])[:num]:
        out["results"].append({
            "title": item.get("title"),
            "link": item.get("link"),
            "snippet": (item.get("snippet") or "")[:280],
            "date": item.get("date"),
            "source": (item.get("source") or {}).get("name") if isinstance(item.get("source"), dict) else item.get("source"),
        })
    if not out["results"]:
        for item in (j.get("news_results") or [])[:num]:
            out["results"].append({
                "title": item.get("title"),
                "link": item.get("link"),
                "snippet": (item.get("snippet") or "")[:280],
                "date": item.get("date"),
                "source": item.get("source"),
            })
    stories = []
    ts = j.get("top_stories")
    items = (ts.get("items") if isinstance(ts, dict) else ts) or []
    for st in list(items)[:4]:
        if isinstance(st, dict) and st.get("title"):
            stories.append({"title": st.get("title"), "link": st.get("link"), "source": st.get("source")})
    if stories:
        out["top_stories"] = stories
    overview = j.get("ai_overview") or {}
    text_blocks = overview.get("text_blocks") or []
    if text_blocks:
        out["ai_overview"] = " ".join(b.get("snippet", "") for b in text_blocks if isinstance(b, dict))[:700]
    rs = j.get("related_searches")
    related = [q.get("query") for q in (rs if isinstance(rs, list) else [])[:5] if isinstance(q, dict)]
    if related:
        out["related"] = related
    return out


def main(query: str = "", num: int = 6, kind: str = "web", hl: str = "en", gl: str = "hk") -> str:
    """Real Google Search results via SerpApi, including news and an AI overview. Use this for
    web search when result quality matters: it returns Google's own ranking, snippets, top
    stories and related searches, unlike the scraped Chinese engines."""
    if not (query or "").strip():
        out = json.dumps({"error": "query required"})
        print(out)
        return out
    result = _search(query.strip(), num=max(1, min(int(num or 6), 15)),
                     kind=(kind or "web").strip().lower(), hl=hl, gl=gl)
    out = json.dumps(result, indent=1, ensure_ascii=False)
    print(out)
    return out

"""Own calendar and scheduled reminders: add, list or remove events that fire as Android
notifications. Events can repeat daily, and can carry a prompt that opens the chat.
Times: "at" takes 'YYYY-MM-DD HH:MM' local time, or use "minutes" for a relative reminder."""
import json
import time

BASE = "/data/user/0/com.niki914.zafiro.evergrow.debug/files/"


def _app():
    from com.chaquo.python import Python as CQ
    return CQ.getPlatform().getApplication()


def _store():
    """Kotlin object -> Java 单例，方法要挂在 INSTANCE 上，否则 unbound method。"""
    from com.niki914.zafiro.app.schedule import ScheduleStore
    return ScheduleStore.INSTANCE


def _parse_at(at):
    if not at:
        return None
    s = at.strip()
    for fmt in ("%Y-%m-%d %H:%M", "%Y-%m-%dT%H:%M", "%Y-%m-%d %H:%M:%S"):
        try:
            return int(time.mktime(time.strptime(s, fmt)) * 1000)
        except ValueError:
            continue
    return None


def _fmt(ms):
    return time.strftime("%Y-%m-%d %H:%M", time.localtime(ms / 1000.0))


def _run(action="list", title="", at="", minutes=0, daily=False, prompt="", event_id=0):
    ctx = _app()
    store = _store()
    act = (action or "list").strip().lower()

    if act == "add":
        if not title.strip():
            return {"error": "title required"}
        when = _parse_at(at)
        if when is None and minutes:
            when = int(time.time() * 1000) + int(minutes) * 60_000
        if when is None:
            return {"error": "give either at='YYYY-MM-DD HH:MM' or minutes=N"}
        obj = store.add(ctx, title.strip(), when, bool(daily), prompt or None)
        return {
            "added": True,
            "id": obj.getLong("id"),
            "title": obj.getString("title"),
            "when": _fmt(obj.getLong("at")),
            "daily": bool(daily),
        }

    if act in ("remove", "delete"):
        if not event_id:
            return {"error": "event_id required"}
        return {"removed": bool(store.remove(ctx, int(event_id))), "id": int(event_id)}

    arr = store.list(ctx)
    events = []
    for i in range(arr.length()):
        o = arr.getJSONObject(i)
        p = o.optString("prompt")
        events.append({
            "id": o.optLong("id"),
            "title": o.optString("title"),
            "when": _fmt(o.optLong("at")),
            "daily": bool(o.optBoolean("daily")),
            "prompt": p if p and p != "null" else None,
        })
    events.sort(key=lambda e: e["when"])
    return {"count": len(events), "now": _fmt(time.time() * 1000), "events": events}


def main(action: str = "list", title: str = "", at: str = "", minutes: int = 0,
         daily: bool = False, prompt: str = "", event_id: int = 0) -> str:
    """Own calendar and scheduled reminders: add, list or remove events that fire as Android
    notifications. Events can repeat daily, and can carry a prompt that opens the chat.
    Times: "at" takes 'YYYY-MM-DD HH:MM' local time, or use "minutes" for a relative reminder."""
    out = json.dumps(_run(action, title, at, minutes, daily, prompt, event_id),
                     indent=1, ensure_ascii=False)
    print(out)
    return out

"""A stopwatch with persistent state: start, lap, status, stop. Elapsed times are real
monotonic-ish wall-clock times, so they survive between tool calls. Use it whenever the user
says "time me", "start a stopwatch", "how long so far", "stop the timer"."""
import json
import os
import time

BASE = "/data/user/0/com.niki914.zafiro.evergrow.debug/files/tool_output/"
PATH = BASE + "stopwatch.json"


def _now_ms():
    return int(time.time() * 1000)


def _load():
    try:
        with open(PATH) as fh:
            return json.load(fh)
    except Exception:
        return None


def _save(state):
    os.makedirs(BASE, exist_ok=True)
    with open(PATH, "w") as fh:
        json.dump(state, fh)


def _fmt(ms):
    total = ms / 1000.0
    m = int(total // 60)
    s = total - m * 60
    if m:
        return "%d:%05.2f" % (m, s)
    return "%.2f" % s


def _elapsed(state):
    now = state.get("stopped_at") or _now_ms()
    return now - state["started_at"]


def _run(action="status"):
    act = (action or "status").strip().lower()
    state = _load()

    if act in ("start", "reset", "restart"):
        fresh = {"started_at": _now_ms(), "stopped_at": None, "laps": []}
        _save(fresh)
        return {"started": True, "at": time.strftime("%H:%M:%S"),
                "note": "Say 'lap' for splits, 'stop' to finish."}

    if state is None:
        return {"error": "No stopwatch running.", "hint": "Call with action=start first."}

    if act == "lap":
        state.setdefault("laps", []).append(_elapsed(state))
        _save(state)
        return {"lap": len(state["laps"]), "elapsed": _fmt(_elapsed(state)),
                "laps": [_fmt(x) for x in state["laps"]]}

    if act in ("stop", "end"):
        if not state.get("stopped_at"):
            state["stopped_at"] = _now_ms()
            _save(state)
        total = _elapsed(state)
        out = {"stopped": True, "elapsed": _fmt(total), "elapsed_ms": total}
        if state.get("laps"):
            out["laps"] = [_fmt(x) for x in state["laps"]]
        return out

    total = _elapsed(state)
    return {"running": not state.get("stopped_at"), "elapsed": _fmt(total),
            "elapsed_ms": total,
            "laps": [_fmt(x) for x in state.get("laps") or []]}


def main(action: str = "status") -> str:
    """A stopwatch with persistent state: start, lap, status, stop. Elapsed times are real
    monotonic-ish wall-clock times, so they survive between tool calls. Use it whenever the user
    says "time me", "start a stopwatch", "how long so far", "stop the timer"."""
    out = json.dumps(_run(action), indent=1)
    print(out)
    return out

