"""Search the Cantonese dictionary (83k entries, words.hk plus personal notes) held in
Firestore. Four ways in: by Chinese character or word, by English meaning, or by Jyutping.
Short words are ranked above sentences so lookups return vocabulary first."""
import json
import re
import urllib.parse

import requests

KEY_FILE = "/data/user/0/com.niki914.zafiro.evergrow.debug/files/firestore_key.txt"
PROJECT, DATABASE = "evergrow-512103", "evergrow-db"
BASE = f"https://firestore.googleapis.com/v1/projects/{PROJECT}/databases/{DATABASE}/documents"


def _key():
    with open(KEY_FILE) as fh:
        return fh.read().strip()


def _fields(doc):
    f = doc.get("fields") or {}
    return {
        "word": f.get("word", {}).get("stringValue", ""),
        "jyutping": f.get("jyutping", {}).get("stringValue", ""),
        "pos": f.get("pos", {}).get("stringValue", ""),
        "english": f.get("english", {}).get("stringValue", ""),
    }


def _run_query(body):
    r = requests.post(f"{BASE}:runQuery", params={"key": _key()}, json={"structuredQuery": body}, timeout=12)
    if r.status_code != 200:
        return []
    out = []
    for item in r.json():
        doc = item.get("document")
        if doc:
            out.append(_fields(doc))
    return out


def _rank(entries, limit):
    """词优先：短的、没有括号标注的、gloss 短的排前面。"""
    def score(e):
        w = e["word"]
        penalty = 0
        if len(w) > 12: penalty += 100
        if w.startswith("(") or w.startswith("（"): penalty += 60
        if e["english"].lower().startswith("(yue)") or e["english"].lower().startswith("(eng)"): penalty += 40
        return (penalty + len(w), len(e["english"]))
    seen, out = set(), []
    for e in sorted(entries, key=score):
        if e["word"] in seen:
            continue
        seen.add(e["word"])
        out.append(e)
        if len(out) >= limit:
            break
    return out


def _by_char(q, limit):
    body = {"from": [{"collectionId": "entries"}],
            "where": {"fieldFilter": {"field": {"fieldPath": "chars"}, "op": "ARRAY_CONTAINS",
                                      "value": {"stringValue": q}}},
            "limit": max(60, limit * 15)}
    return _run_query(body)


def _by_prefix(field, q, limit):
    body = {"from": [{"collectionId": "entries"}],
            "where": {"compositeFilter": {"op": "AND", "filters": [
                {"fieldFilter": {"field": {"fieldPath": field}, "op": "GREATER_THAN_OR_EQUAL",
                                 "value": {"stringValue": q}}},
                {"fieldFilter": {"field": {"fieldPath": field}, "op": "LESS_THAN",
                                 "value": {"stringValue": q + "\uf8ff"}}}]}},
            "limit": max(40, limit * 12)}
    return _run_query(body)


def _by_english(q, limit):
    tokens = [t for t in re.findall(r"[a-z]{2,}", q.lower())]
    results = []
    for t in tokens[:2]:
        body = {"from": [{"collectionId": "entries"}],
                "where": {"fieldFilter": {"field": {"fieldPath": "eng_tokens"}, "op": "ARRAY_CONTAINS",
                                          "value": {"stringValue": t}}},
                "limit": max(60, limit * 15)}
        results += _run_query(body)
    return results


def _exact(q):
    url = BASE + "/entries/" + urllib.parse.quote(q, safe="")
    r = requests.get(url, params={"key": _key()}, timeout=8)
    if r.status_code == 200:
        return [_fields(r.json())]
    return []


def _run(action="auto", query="", limit=5):
    q = (query or "").strip()
    if not q:
        return {"error": "query required"}
    act = (action or "auto").lower()
    if act == "auto":
        if re.search(r"[\u3400-\u9fff]", q):
            act = "word" if len(q) > 1 else "char"
        elif re.match(r"^[a-z]+[1-6]", q):
            act = "jyutping"
        else:
            act = "english"

    if act == "char":
        # 单字要的是「包含这个字的所有词」，不是「正好等于这个字」的条目
        pool = _by_char(q, limit) + _exact(q)
    elif act == "word":
        exact = _exact(q)
        pool = exact if exact else _by_prefix("word", q, limit)
    elif act == "jyutping":
        pool = _by_prefix("jyutping", q, limit)
    elif act == "english":
        pool = _by_english(q, limit)
    else:
        return {"error": "action must be auto, word, char, english or jyutping"}

    ranked = _rank(pool, max(1, min(int(limit or 5), 20)))
    return {"query": q, "mode": act, "found": len(ranked), "entries": ranked}


def main(action: str = "auto", query: str = "", limit: int = 5) -> str:
    """Search the Cantonese dictionary (83k entries, words.hk plus personal notes) held in
    Firestore. Four ways in: by Chinese character or word, by English meaning, or by Jyutping.
    Short words are ranked above sentences so lookups return vocabulary first."""
    out = json.dumps(_run(action, query, limit), indent=1, ensure_ascii=False)
    print(out)
    return out
